import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String raw = new String(System.in.readAllBytes(), "UTF-8");
        ArrayList<Long> list = new ArrayList<>();
        // Items are "city, distance" separated by ';'; the distance follows the last comma.
        for (String item : raw.split(";", -1)) {
            if (item.trim().isEmpty()) continue;
            list.add(Long.parseLong(item.substring(item.lastIndexOf(',') + 1).trim()));
        }
        long[] ds = new long[list.size()];
        for (int i = 0; i < ds.length; i++) ds[i] = list.get(i);
        Arrays.sort(ds);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < ds.length; i++) {
            if (i > 0) sb.append(", ");
            sb.append(i == 0 ? ds[0] : ds[i] - ds[i - 1]);
        }
        System.out.println(sb);
    }
}

