import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	var ds []int
	// Items are "city, distance" separated by ';'; the distance follows the last comma.
	for _, item := range strings.Split(string(data), ";") {
		if strings.TrimSpace(item) == "" {
			continue
		}
		v, _ := strconv.Atoi(strings.TrimSpace(item[strings.LastIndexByte(item, ',')+1:]))
		ds = append(ds, v)
	}
	sort.Ints(ds)
	parts := make([]string, len(ds))
	for i := range ds {
		if i == 0 {
			parts[i] = strconv.Itoa(ds[0])
		} else {
			parts[i] = strconv.Itoa(ds[i] - ds[i-1])
		}
	}
	fmt.Println(strings.Join(parts, ", "))
}
